    "path": "union-acceptance/readable-paths/dot-root-traversal.test.mjs",
    "text": "import { test } from 'node:test'; import assert from 'node:assert'; import { mkdtempSync, writeFileSync, mkdirSync, rmSync } from 'node:fs'; import { join } from 'node:path'; import { tmpdir } from 'node:os'; import { createAgentTools } from '../../src/agent-tools.mjs'; test('dot-root-traversal', async (t) => { const root = mkdtempSync(join(tmpdir(), 'traversal-')); const publicDir = join(root, 'public'); const privateDir = join(root, 'private'); mkdirSync(publicDir); mkdirSync(privateDir); writeFileSync(join(publicDir, 'public.txt'), 'find-me'); writeFileSync(join(privateDir, 'secret.txt'), 'find-me'); const tools = createAgentTools({ root, readablePaths: ['public'] }); t.after(() => rmSync(root, { recursive: true, force: true })); const listRes = JSON.parse(tools.execute({ action: 'list_files', args: { path: '.' } })); assert.ok(!listRes.error, 'Should not error on dot'); assert.ok(listRes.files.includes('public/public.txt'), 'Public file should be admitted'); assert.ok(!listRes.files.includes('private/secret.txt'), 'Private file must be excluded'); const searchRes = JSON.parse(tools.execute({ action: 'search', args: { path: '.', query: 'find-me' } })); assert.ok(!searchRes.error, 'Search on dot should not error'); assert.strictEqual(searchRes.hits.length, 1, 'Only one public hit expected'); assert.strictEqual(searchRes.hits[0].path, 'public/public.txt', 'Hit must be within public path'); const serialized = JSON.stringify(searchRes); assert.ok(!serialized.includes('secret.txt'), 'Serialized response must omit private filenames'); assert.ok(!serialized.includes('find-me') || searchRes.hits[0].path === 'public/public.txt', 'Serialized response should not contain private file context'); });"
  },
  "rationale": "The test creates a temporary directory structure containing both public and private subdirectories, initializes the agent tools with only the public path as readable, and validates that '.' (root) traversal correctly filters out private files in both listing and searching, ensuring no data leakage for unauthorized paths."
}

